import { chromium } from 'playwright';
import fs from 'fs';

const email = `auditor.${Date.now()}@example.com`;
const password = 'AuditPass123!';
const name = 'Audit Tester';

fs.writeFileSync('/tmp/audit-creds.json', JSON.stringify({ email, password, name }, null, 2));

const browser = await chromium.launch();

// Register fresh account
{
  const page = await browser.newPage();
  page.on('console', msg => { if (msg.type() === 'error') console.log('FRESH-REG CONSOLE ERROR:', msg.text()); });
  page.on('pageerror', err => console.log('FRESH-REG PAGE ERROR:', err.message));
  await page.goto('http://localhost:3021/register', { waitUntil: 'networkidle' });
  await page.fill('#register-name', name);
  await page.fill('#register-email', email);
  await page.fill('#register-password', password);
  await page.click('button[type=submit]');
  await page.waitForTimeout(3000);
  console.log('After register, URL:', page.url());
  await page.screenshot({ path: '/tmp/after-register.png' });
  await page.context().storageState({ path: '/opt/nxeon-v2/.auth-fresh.json' });
  await page.close();
}

// Login admin
{
  const page = await browser.newPage();
  page.on('console', msg => { if (msg.type() === 'error') console.log('ADMIN-LOGIN CONSOLE ERROR:', msg.text()); });
  page.on('pageerror', err => console.log('ADMIN-LOGIN PAGE ERROR:', err.message));
  await page.goto('http://localhost:3021/login', { waitUntil: 'networkidle' });
  const fields = await page.$$eval('input', els => els.map(e => ({ name: e.name, type: e.type, id: e.id })));
  console.log('LOGIN FIELDS:', JSON.stringify(fields));
  await page.fill('#login-email, input[type=email]', 'admin@nxeon.local').catch(async () => {
    await page.fill('input[name=email]', 'admin@nxeon.local');
  });
  await page.fill('#login-password, input[type=password]', 'iCwEt7PDdo0ne3YM').catch(async () => {
    await page.fill('input[name=password]', 'iCwEt7PDdo0ne3YM');
  });
  await page.click('button[type=submit]');
  await page.waitForTimeout(3000);
  console.log('After admin login, URL:', page.url());
  await page.screenshot({ path: '/tmp/after-admin-login.png' });
  await page.context().storageState({ path: '/opt/nxeon-v2/.auth-admin.json' });
  await page.close();
}

await browser.close();
console.log('DONE');

