1	import { headers } from "next/headers";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { clientIp } from "@/lib/rate-limit";
5	import { hashIp } from "@/lib/coupon-order";
6	import { firstMonthFreeEligible, firstMonthFreeEnabled, firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
7	import { annualDiscountPct } from "@/lib/annual-discount";
8	import { extraDiskPerGbCents } from "@/lib/disk-expand";
9	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
10	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
11	import { VPS_TERMS, vpsTermPriceCents, termPriceCents, termDiscountPct } from "@/lib/billing-terms";
12	import { regionsFrom, appSpriteKey, gameArt } from "@/lib/nx/catalog";
13	import { GAME_DISPLAY, GAME_GENRES, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";
14	import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
15	import { GAME_FAMILIES } from "@/lib/games";
16	import { stripeConfigured } from "@/lib/stripe";
17	import { paypalConfigured } from "@/lib/paypal";
18	import { coinbaseConfigured } from "@/lib/coinbase-commerce";
19	import { DeployView } from "@/components/nx/DeployView";
20	import type { AddonOption, EmailPlanOption, GameFamilyOption, HostingPlanOption, OsOption, PlanOption, TermOption } from "@/components/nx/order-types";
21	
22	/* Data for the VPS deploy wizard.
23	 *
24	 * The one rule this file exists to keep: every number the wizard can display is
25	 * computed HERE, by the same functions that charge the card, and handed down
26	 * already worked out. The view prints; it never multiplies.
27	 *
28	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
29	 * rate plus a discount percent. Sending the percent would mean the browser does
30	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
31	 * when the customer decides. Terms are few and plans are few, so the matrix is
32	 * cheap and it cannot drift from `vpsTermPriceCents`.
33	 */
34	
35	/* Icon per image, keyed off the platform's own `family` value rather than
36	   sniffing the display name. Control panels and applications have families too
37	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
38	const ICON_BY_FAMILY: Record<string, string> = {
39	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
40	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
41	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
42	  mysql: "mysql", postgres: "postgres", redis: "redis",
43	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
44	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
45	};
46	function osIcon(family: string, category: string): string {
47	  return ICON_BY_FAMILY[family?.toLowerCase()]
48	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
49	}
50	
51	export default async function NxDeployPage() {
52	  const user = await requireUser();
53	
54	  // Real, per-customer eligibility for the first-month-free hosting promo —
55	  // NOT a display detail, the exact same advisory pre-check
56	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
57	  // wizard's hosting/email price was a flat, precomputed matrix with zero
58	  // per-user awareness (deliberately: "so there is no round-trip to make"),
59	  // which is why the promo's own plan-card badge ("First month free") and
60	  // the wizard's actual total disagreed — the matrix could not have known
61	  // whether THIS customer still qualifies. One extra check here, resolved
62	  // alongside the rest of this page's own data fetching.
63	  const hostingPromoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
64	  const hostingPromoEligible =
65	    firstMonthFreeAppliesTo("HOSTING") &&
66	    (await firstMonthFreeEnabled()) &&
67	    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));
68	
69	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
70	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
71	    /* All three categories — the design's Server settings panel has a tab per
72	       category (Operating system / Control panels / Applications), which is
73	       exactly what ImageCategory already distinguishes. They are separated in
74	       the VIEW, not filtered out here: a game-server image is a real thing you
75	       can deploy, it just is not an answer to "pick an operating system". */
76	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
77	       images, but Nxeon sells game servers as their own product with their own
78	       plans, panel and pricing — offering "Minecraft Server" as a VPS
79	       application sells the same thing twice, at the wrong price, without the
80	       game panel. Identified by `family` against the platform's own
81	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
82	    db.osTemplate.findMany({
83	      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
84	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
85	    }),
86	    // enabled only — a disabled node is not a place we can provision.
87	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
88	    // "from" prices for the service tiles — the cheapest live plan of each kind,
89	    // read from the same tables the order path prices against.
90	    // Every active tier: the wizard groups them into families itself, so one
91	    // query serves both the "from" price on the tiles and the tier picker.
92	    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
93	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
94	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
95	    annualDiscountPct(),
96	    extraDiskPerGbCents(),
97	    dedicatedIpMonthlyCents(),
98	    backupPlusMonthlyCents(),
99	  ]);
100	
101	  /* The monthly term is the reference rate the cards show by default; the wizard
102	     re-reads this matrix when the customer changes term. Priced through
103	     `vpsTermPriceCents`, the same helper `orderQuote` uses. */
104	  const priceMatrix: Record<string, Record<number, number>> = {};
105	  for (const p of plans) {
106	    priceMatrix[p.id] = {};
107	    for (const t of VPS_TERMS) {
108	      // term total / months = the effective monthly rate at that term
109	      priceMatrix[p.id][t.months] = Math.round(
110	        vpsTermPriceCents(p.priceCents, t.months, annualPct) / t.months
111	      );
112	    }
113	  }
114	
115	  /* "Recommended" is the middle of the ladder, not the most expensive — the
116	     default has to be a defensible choice, not an upsell. */
117	  const recommendedId = plans.length ? plans[Math.floor((plans.length - 1) / 2)].id : null;
118	
119	  const planOptions: PlanOption[] = plans.map((p) => ({
120	    id: p.id,
121	    slug: p.slug,
122	    name: p.name,
123	    cpuCores: p.cpuCores,
124	    ramMB: p.ramMB,
125	    diskGB: p.diskGB,
126	    bandwidthTB: p.bandwidthTB,
127	    monthlyCents: p.priceCents,
128	    effectiveMonthlyCents: priceMatrix[p.id][1],
129	    introMonthlyCents: p.introPriceCents ?? null,
130	    introRenewalMonthlyCents: p.introPriceCents ? p.priceCents : null,
131	    recommended: p.id === recommendedId,
132	  }));
133	
134	  const osOptions: OsOption[] = oses.map((o) => ({
135	    id: o.id,
136	    name: o.name,
137	    version: o.version ?? "",
138	    icon: osIcon(o.family, o.category),
139	    category: o.category,
140	    family: o.family,
141	    spriteKey: o.category === "PLAIN_OS" ? null : appSpriteKey(o.name),
142	  }));
143	
144	  const termOptions: TermOption[] = VPS_TERMS.map((t) => ({
145	    months: t.months,
146	    label: t.label,
147	    discountPercent: termDiscountPct(t.months, annualPct),
148	  }));
149	
150	  /* Add-on rates come from the same functions the charge path reads. A rate
151	     hardcoded next to a checkbox is how a display price and a charged price
152	     drift apart. */
153	  /* Families are built from the tiers that actually exist. A family with no
154	     active plan is not offered — the alternative is a card that leads to an
155	     empty tier list. Variants and the subdomain requirement come from the
156	     platform's own family schema, not from a list kept here. */
157	  // Leads the game grid, in this order, each badged "Popular" — the owner's
158	  // pick, not a computed ranking (no real play-count/order-volume signal
159	  // exists yet to rank by). `projectzomboid`/`sdtd` are the actual family
160	  // keys behind "Project Zomboid" / "7 Days to Die" (lib/games.ts
161	  // GAME_FAMILIES) — the display names aren't the lookup keys.
162	  const POPULAR_GAME_ORDER = ["minecraft", "rust", "valheim", "palworld", "projectzomboid", "terraria"];
163	  const gameFamilies: GameFamilyOption[] = (() => {
164	    const byFamily = new Map<string, typeof gamePlans>();
165	    for (const gp of gamePlans) {
166	      const list = byFamily.get(gp.gameFamily) ?? [];
167	      list.push(gp);
168	      byFamily.set(gp.gameFamily, list);
169	    }
170	    return [...byFamily.entries()].map(([family, tiers]) => {
171	      const schema = GAME_CONFIG_SCHEMAS[family];
172	      return {
173	        family,
174	        name: GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family,
175	        art: gameArt(family),
176	        variants: schema?.variants ?? [],
177	        defaultVariant: schema?.defaultVariant ?? "",
178	        genres: GAME_GENRES[family as keyof typeof GAME_GENRES] ?? [],
179	        /* Same source of truth quoteGameOrder (lib/game-order.ts) charges
180	           through — a second, hand-maintained "just minecraft" check here
181	           silently left every other hostname-connect family (ARK, the
182	           Source-engine titles, Satisfactory, Conan, 7 Days to Die,
183	           Enshrouded, and more) without a "Play address" field to fill in,
184	           so their orders could reach the payment step with no subdomain
185	           and no way to price. */
186	        needsSubdomain: family === "minecraft" || family === "bedrock"
187	          || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
188	        fromCents: Math.min(...tiers.map((t) => t.priceCents)),
189	        popular: POPULAR_GAME_ORDER.includes(family),
190	        tiers: tiers.map((t) => ({
191	          id: t.id,
192	          name: t.name,
193	          ramMB: t.ramMB,
194	          cpuCores: t.cpuCores,
195	          diskGB: t.diskGB,
196	          slots: t.slots ?? null,
197	          monthlyCents: t.priceCents,
198	          termMonths: t.termMonths,
199	        })),
200	      };
201	    }).sort((a, b) => {
202	      const pa = POPULAR_GAME_ORDER.indexOf(a.family);
203	      const pb = POPULAR_GAME_ORDER.indexOf(b.family);
204	      if (pa !== -1 || pb !== -1) return (pa === -1 ? 999 : pa) - (pb === -1 ? 999 : pb);
205	      return a.name.localeCompare(b.name);
206	    });
207	  })();
208	
209	  const hostingOptions: HostingPlanOption[] = hostingPlans.map((h) => ({
210	    id: h.id, name: h.name, tagline: h.tagline,
211	    diskGB: h.diskGB, maxSites: h.maxSites, maxDatabases: h.maxDatabases,
212	    bandwidthTB: h.bandwidthTB, mailboxes: h.mailboxes,
213	    freeMigration: h.freeMigration, featured: h.featured,
214	    monthlyCents: h.priceCents,
215	  }));
216	
217	  const emailOptions: EmailPlanOption[] = emailPlans.map((e) => ({
218	    id: e.id, name: e.name, mailboxes: e.mailboxes,
219	    storageGB: e.storageGB, monthlyCents: e.priceCents, termMonths: e.termMonths,
220	  }));
221	
222	  /* Hosting and email price through `termPriceCents` — the same helper their
223	     own charge paths use (lib/actions-hosting.ts, lib/actions-email-hosting.ts).
224	     Built as a matrix for the same reason as the VPS one: sending a rate and a
225	     discount percent would put the multiply back in the browser. */
226	  const hostingMatrix: Record<string, Record<number, number>> = {};
227	  // One month of the plan's own rate, credited when this customer still
228	  // qualifies — same shape as the VPS quote's `regularPlanCents - plan.priceCents`
229	  // (lib/order.ts), just carried alongside the matrix instead of computed by
230	  // a server round-trip. 0 (no credit) once first_month_free is off, already
231	  // claimed on this account/IP, or the plan changes and this needs recomputing.
232	  const hostingFirstMonthFreeCents: Record<string, number> = {};
233	  for (const h of hostingPlans) {
234	    hostingMatrix[h.id] = {};
235	    for (const t of VPS_TERMS) {
236	      hostingMatrix[h.id][t.months] = Math.round(termPriceCents(h.priceCents, t.months, annualPct) / t.months);
237	    }
238	    hostingFirstMonthFreeCents[h.id] = hostingPromoEligible ? h.priceCents : 0;
239	  }
240	  const emailMatrix: Record<string, Record<number, number>> = {};
241	  for (const e of emailPlans) {
242	    emailMatrix[e.id] = {};
243	    for (const t of VPS_TERMS) {
244	      emailMatrix[e.id][t.months] = Math.round(termPriceCents(e.priceCents, t.months, annualPct) / t.months);
245	    }
246	  }
247	
248	  const addonOptions: AddonOption[] = [
249	    { key: "backup", name: "Backup Plus", note: "Longer retention, more restore points", icon: "archive", monthlyCents: backupCents, free: false },
250	    { key: "ip", name: "Dedicated IP", note: "An address of your own", icon: "nodes", monthlyCents: ipCents, free: false },
251	    { key: "malware", name: "Malware scanning", note: "Scheduled scans and alerts", icon: "shieldcheck", monthlyCents: 0, free: true },
252	    { key: "docker", name: "Docker pre-installed", note: "Ready for containers on first boot", icon: "docker", monthlyCents: 0, free: true },
253	  ];
254	
255	  return (
256	    <DeployView
257	      cat={{
258	        plans: planOptions,
259	        games: gameFamilies,
260	        hosting: hostingOptions,
261	        email: emailOptions,
262	        hostingMatrix,
263	        hostingFirstMonthFreeCents,
264	        emailMatrix,
265	        oses: osOptions,
266	        terms: termOptions,
267	        addons: addonOptions,
268	        // Only regions where a Node actually exists — the wizard can never sell a
269	        // location we cannot provision in.
270	        regions: regionsFrom(nodes),
271	        diskPerGbCents,
272	        walletCents: user.balanceCents,
273	      }}
274	      priceMatrix={priceMatrix}
275	      hostingMatrix={hostingMatrix}
276	      emailMatrix={emailMatrix}
277	      firstName={user.name.split(" ")[0]}
278	      /* Which payment methods to OFFER. Read from the same predicates the
279	         charge paths use, so a method is never shown unless the platform can
280	         actually take money through it. In this sandbox all three are false by
281	         design, which is why the wallet is the only way to pay here. */
282	      methods={{
283	        card: stripeConfigured(),
284	        paypal: paypalConfigured(),
285	        crypto: coinbaseConfigured(),
286	      }}
287	      /* PayPal's PUBLIC client id. Safe to send to the browser — it is what the
288	         PayPal SDK script is keyed on and appears in every PayPal integration's
289	         page source. The SECRET stays on the server, where `createPayPalOrder`
290	         uses it. Null unless PayPal is actually configured, so the wizard can
291	         never mount the SDK against an empty id. */
292	      paypalClientId={paypalConfigured() ? process.env.PAYPAL_CLIENT_ID ?? null : null}
293	      fromCents={{
294	        vps: plans[0]?.priceCents ?? null,
295	        game: gamePlans.length ? Math.min(...gamePlans.map((g) => g.priceCents)) : null,
296	        hosting: hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null,
297	        email: emailPlans.length ? Math.min(...emailPlans.map((e) => e.priceCents)) : null,
298	        // No fixed plan row for domains — real price is a live per-TLD
299	        // registrar quote. 999 ($9.99) used to stand in here as a flat
300	        // guess; `null` renders this tile's existing "Pricing unavailable"
301	        // fallback instead of a number that isn't real.
302	        domains: null,
303	      }}
304	    />
305	  );
306	}
307

