import { chromium } from 'playwright';

const browser = await chromium.launch();
const ctx = await browser.newContext({ storageState: '/opt/nxeon-v2/.auth-admin.json', viewport: { width: 1600, height: 1000 } });
const page = await ctx.newPage();
page.on('console', msg => { if (msg.type() === 'error') console.log('CONSOLE ERROR:', msg.text()); });
page.on('pageerror', err => console.log('PAGE ERROR:', err.message));

await page.goto('http://localhost:3021/dashboard/deploy', { waitUntil: 'networkidle' });
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/audit-shots/00-landing.png', fullPage: true });

// Dump text content structure of visible buttons / headings
const headings = await page.$$eval('h1,h2,h3', els => els.map(e => e.textContent.trim()));
console.log('HEADINGS:', JSON.stringify(headings));

const buttons = await page.$$eval('button', els => els.slice(0,60).map(e => e.textContent.trim()).filter(Boolean));
console.log('BUTTONS:', JSON.stringify(buttons));

await browser.close();

import { chromium } from 'playwright';

export async function newPage({ account = 'admin', theme = 'dark', width = 1600, height = 1000, label = '' } = {}) {
  const browser = await chromium.launch();
  const storageState = account === 'admin' ? '/opt/nxeon-v2/.auth-admin.json' : '/opt/nxeon-v2/.auth-fresh.json';
  const ctx = await browser.newContext({ storageState, viewport: { width, height } });
  if (theme === 'light') {
    await ctx.addInitScript(() => { try { localStorage.setItem('nx-theme', 'light'); } catch {} });
  }
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') {
      errors.push(msg.text());
      console.log(`[${label}] CONSOLE ERROR:`, msg.text());
    }
  });
  page.on('pageerror', err => {
    errors.push(err.message);
    console.log(`[${label}] PAGE ERROR:`, err.message);
  });
  return { browser, ctx, page, errors };
}

export async function dismissCookie(page) {
  try {
    const btn = page.locator('button:has-text("Got it")');
    if (await btn.isVisible({ timeout: 2000 })) await btn.click();
  } catch {}
}

