import { newPage, dismissCookie } from './.audit-lib.mjs';

const combos = [
  ['admin', 'dark', 1600], ['admin', 'dark', 1900],
  ['admin', 'light', 1600], ['admin', 'light', 1900],
  ['fresh', 'dark', 1600], ['fresh', 'dark', 1900],
  ['fresh', 'light', 1600], ['fresh', 'light', 1900],
];

for (const [account, theme, width] of combos) {
  const tag = `sweep-${account}-${theme}-${width}`;
  const { browser, page, errors } = await newPage({ account, theme, width, height: 1000, label: tag });
  await page.goto('http://localhost:3021/dashboard/deploy', { waitUntil: 'networkidle' });
  await dismissCookie(page);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/audit-shots/${tag}-landing.png`, fullPage: true });

  // walk into VPS quickly and game quickly to catch errors in those bands too
  await page.click('text=VPS Servers');
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/audit-shots/${tag}-vps.png`, fullPage: true });
  await page.click('text=Back');
  await page.waitForTimeout(600);
  await page.click('text=Game Servers');
  await page.waitForTimeout(700);
  await page.screenshot({ path: `/tmp/audit-shots/${tag}-game.png`, fullPage: true });

  console.log(`=== ${tag} === errors: ${errors.length ? JSON.stringify(errors) : 'none'}`);
  await browser.close();
}

